WITH kept_keys AS (SELECT account_id, merchant FROM transactions EXCEPT SELECT account_id, merchant FROM transactions WHERE txn_type != 'CREDIT'), reconciled AS (SELECT s.* FROM transactions s JOIN kept_keys k ON s.account_id = k.account_id AND s.merchant = k.merchant) SELECT DATE_TRUNC('WEEK', txn_time) AS week_start, DATE_TRUNC('YEAR', txn_time) AS year_start, CASE WHEN amount >= 4200 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END), 0), 2) AS amount_per_7_eleven, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', txn_time) ORDER BY ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END), 0), 2) DESC) AS amount_per_7_eleven_percent_rank FROM reconciled GROUP BY DATE_TRUNC('WEEK', txn_time), DATE_TRUNC('YEAR', txn_time), CASE WHEN amount >= 4200 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END), 0), 2) >= 0;
